const arrival=document.querySelector('#arrival');const skipIntro=document.querySelector('#skipIntro');let introTimer;function finishIntro(){if(!arrival||arrival.classList.contains('done'))return;clearTimeout(introTimer);arrival.classList.add('done');setTimeout(()=>arrival.remove(),900)}skipIntro?.addEventListener('click',finishIntro);introTimer=setTimeout(finishIntro,4800);if(matchMedia('(prefers-reduced-motion: reduce)').matches)introTimer=setTimeout(finishIntro,900);
const scenes=[...document.querySelectorAll('.scene')];const fill=document.querySelector('.progress-fill');const counter=document.querySelector('#counter');let current=0,locked=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function go(n){n=Math.max(0,Math.min(scenes.length-1,n));if(n===current||locked)return;locked=true;scenes[current].classList.remove('active');scenes[current].classList.add('leaving');const old=current;current=n;scenes[current].classList.add('active');fill.style.width=`${(current+1)/scenes.length*100}%`;counter.innerHTML=`${String(current+1).padStart(2,'0')} <i>/</i> 07`;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===scenes.length-1;setTimeout(()=>{scenes[old].classList.remove('leaving');locked=false},reduced?40:850)}document.querySelector('#prev').disabled=true;fill.style.width=`${100/scenes.length}%`;document.querySelector('#next').addEventListener('click',()=>go(current+1));document.querySelector('#prev').addEventListener('click',()=>go(current-1));document.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>go(current+1)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.go))));document.querySelector('#discover').addEventListener('click',()=>go(2));let lastWheel=0;window.addEventListener('wheel',e=>{if(Math.abs(e.deltaY)<8)return;e.preventDefault();const now=Date.now();if(now-lastWheel<900)return;lastWheel=now;go(current+(e.deltaY>0?1:-1))},{passive:false});window.addEventListener('keydown',e=>{if(['ArrowDown','ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(current+1)}if(['ArrowUp','ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}if(e.key==='Home')go(0);if(e.key==='End')go(6)});let startY=0;window.addEventListener('touchstart',e=>startY=e.touches[0].clientY,{passive:true});window.addEventListener('touchend',e=>{const dy=startY-e.changedTouches[0].clientY;if(Math.abs(dy)>45)go(current+(dy>0?1:-1))},{passive:true});
